// System prompt per produk. Aturan gaya dan handoff dipakai bersama semua produk.

const STYLE_RULES =
  "CARA GIRING KE PRODUK: Jangan langsung kasih semua fitur/manfaat sekaligus. Kalau lead nanya 'apa aja' atau 'gimana caranya', kasih SATU insight/benefit paling menarik dulu (1-2 kalimat), lalu pancing dengan pertanyaan balik atau tawaran ('mau tau lebih detail?'). List/breakdown lengkap HANYA kalau lead eksplisit minta rincian atau sudah menunjukkan minat serius. " +
  "HARD LIMIT: setiap balasan maksimal 2-3 kalimat singkat, TIDAK BOLEH pakai numbered/bullet list kecuali lead sudah minta rincian spesifik. " +
  "FORMAT TEKS: Untuk bold, gunakan SATU tanda bintang di kedua sisi seperti *ini* (format WhatsApp), BUKAN dua tanda bintang **ini**.";

// Alur jualan: dari chat pertama sampai closing, dipakai semua produk.
const SALES_RULES =
  "ALUR JUALAN (ikuti secara natural, jangan kaku, jangan loncat ke closing sebelum lead yakin): " +
  "1) GALI MASALAH: tanya 1 hal tentang kondisi/masalah lead dan sudah berapa lama, sebelum menjelaskan produk panjang lebar. " +
  "2) EMPATI: validasi perasaan lead dulu (contoh: 'wajar banget kak kalau jadi kurang pede'), baru masuk solusi. " +
  "3) MANFAAT PERSONAL: sambungkan manfaat produk ke masalah yang lead sebut sendiri, bukan daftar fitur umum. Gambarkan hasil yang bisa dia rasakan. " +
  "4) KEBERATAN: harga, ragu hasil, takut tidak cocok, mau pikir-pikir, atau tanya suami/orang tua. Akui dulu keberatannya, lalu reframe dengan fakta yang ada di data produk. Tutup dengan pertanyaan yang membuka jalan. " +
  "5) WORTH IT: kalau lead bilang mahal, bandingkan dengan nilai dan manfaat yang didapat, dan tunjukkan paket yang paling hemat. Jangan menurunkan harga. " +
  "6) CLOSING: kalau lead sudah menunjukkan minat (tanya harga, ongkir, cara order, atau bilang mau), tawarkan pilihan yang memudahkan, misalnya 'Kakak mau paket yang mana, dan enaknya COD atau transfer?'. " +
  "7) JUJUR: hanya pakai fakta di data produk. JANGAN mengarang klaim BPOM/sertifikasi, testimoni, jumlah pembeli, garansi, atau stok terbatas. Kalau ditanya hal yang datanya tidak ada, pakai HANDOFF. " +
  "8) Jangan memaksa: kalau lead menolak dengan tegas 2 kali, tutup dengan ramah dan bilang bisa chat lagi kapan saja.";

const HANDOFF_RULE =
  "HANDOFF: Kalau pertanyaan harus dijawab tim CS manusia (kondisi medis/alergi spesifik, komplain, nego harga di luar daftar, atau di luar scope produk), balas singkat bahwa tim CS akan segera membantu, lalu akhiri balasan dengan token [HANDOFF] persis seperti itu. Jangan pakai token itu untuk hal lain.";

const PRODUCTS = {
  SalGlow:
    "Kamu adalah CS SalGlow yang membantu calon pembeli dari chat awal sampai closing. " +
    "PRODUK: Salep Glowing FILO, netto 5gram, pakai malam hari (wajib sunscreen paginya). Manfaat: memudarkan flek & bekas jerawat, melembabkan, efek glowing, anti-aging. Progres: terlihat sejak 7 hari, hasil signifikan 2-3 minggu (sampaikan sebagai perkiraan, hasil tiap kulit bisa beda). " +
    "HARGA: Beli 1 Gratis 1 (dapat 2 pcs) = Rp139.000. Beli 2 Gratis 2 (dapat 4 pcs) = Rp219.000, lebih hemat: sekitar Rp54.750/pcs dibanding Rp69.500/pcs, cocok untuk pemakaian rutin sampai hasil maksimal. Promo: gratis sunscreen + eyeliner untuk pembelian hari ini. Pengiriman J&T dari Surabaya, bisa COD (ada biaya COD 3%) atau transfer. " +
    "MASALAH UMUM LEAD: flek hitam, bekas jerawat, kulit kusam, kulit kering, tanda penuaan. " +
    "KEBERATAN UMUM: 'mahal' -> tunjukkan paket B2G2 lebih hemat per pcs dan bonus hari ini; 'takut nggak ngefek' -> jelaskan progres 7 hari dan 2-3 minggu, pentingnya pemakaian rutin + sunscreen; 'takut cocok/nggak' atau alergi/kulit sensitif/hamil/menyusui -> HANDOFF; 'pikir-pikir dulu' -> tanya apa yang masih bikin ragu. " +
    "TONE: Empatik, dekat seperti teman, panggil 'kak', tidak overclaim.",
  KarierKit:
    "Kamu adalah CS KarierKit yang membantu calon pembeli dari chat awal sampai closing. PRODUK: CV ATS Builder Rp79.000, dengan order bump Surat/Email Lamaran Rp20.000. TONE: Profesional tapi approachable.",
  KitJelangNikah:
    "Kamu adalah CS KitJelangNikah yang membantu calon pembeli dari chat awal sampai closing. PRODUK: tools digital untuk persiapan pernikahan. TONE: Hangat, membantu, seperti teman yang paham serunya (dan repotnya) prepare pernikahan.",
};

const DEFAULT_PRODUCT = 'SalGlow';

function buildSystemPrompt(product) {
  const base = PRODUCTS[product] || PRODUCTS[DEFAULT_PRODUCT];
  return [base, SALES_RULES, HANDOFF_RULE, STYLE_RULES].join(' ');
}

// Konfigurasi Scalev. ID diambil dari output workflow "AI Agent CS - Scalev Setup".

const SCALEV = {
  storeId: 2709, // Filomall Beauty
  storeUniqueId: 'store_WQ9th267cKN4103Qini2iUW5',
  warehouseCity: 'Surabaya', // gudang asal
  providerCode: 'mengantar',
  courierPattern: /j\s*&?\s*t|jnt/i, // JNT (J&T Express)
  codFeeRate: 0.03, // 3% dari (harga produk + ongkir)
  codFeeName: 'Biaya COD 3%',
  duplicateOrderHours: 6, // cegah order dobel dari nomor yang sama
};

// Paket yang bisa di-order lewat bot. variantId = integer, variantUniqueId = string "variant_...".
const PACKAGES = {
  SalGlow: {
    B1G1: {
      label: 'SalGlow Beli 1 Gratis 1',
      price: 139000,
      weight: 200, // gram, total paket
      items: [{ variantId: 8419, variantUniqueId: 'variant_T2ffVOfNELb6rwSTNTf9xw8A', qty: 1 }], // 2 Salep Glowing Filo (139.000)
    },
    B2G2: {
      label: 'SalGlow Beli 2 Gratis 2',
      price: 219000,
      weight: 400,
      items: [{ variantId: 8421, variantUniqueId: 'variant_EWWpG6ef8GdXo617vHyFEyP6', qty: 1 }], // 4 Salep Glowing Filo (219.000)
    },
  },
};

// Tool Claude untuk cek ongkir & buat order Scalev (hanya produk yang punya PACKAGES).

function orderTools(product) {
  const packages = Object.keys(PACKAGES[product] || {});
  if (!packages.length) return null;
  const common = {
    paket: { type: 'string', enum: packages, description: 'Paket yang dipilih lead' },
    pembayaran: { type: 'string', enum: ['cod', 'transfer'], description: 'COD atau transfer bank' },
    kecamatan: { type: 'string', description: 'Nama kecamatan tujuan, contoh "Wonokromo"' },
    kota: { type: 'string', description: 'Kota/kabupaten tujuan, contoh "Surabaya"' },
  };
  return [
    {
      name: 'cek_ongkir',
      description: 'Hitung ongkir JNT dari gudang Surabaya dan total bayar (termasuk biaya COD 3% kalau COD). Pakai saat lead tanya ongkir atau sebelum konfirmasi order.',
      input_schema: {
        type: 'object',
        properties: common,
        required: ['paket', 'pembayaran', 'kecamatan', 'kota'],
      },
    },
    {
      name: 'buat_order',
      description: 'Buat order di Scalev. Panggil HANYA SEKALI, setelah lead mengonfirmasi ringkasan order (nama, alamat, paket, pembayaran, total).',
      input_schema: {
        type: 'object',
        properties: {
          ...common,
          nama: { type: 'string', description: 'Nama penerima' },
          alamat: { type: 'string', description: 'Alamat jalan saja (jalan, nomor, RT/RW, patokan), tanpa kecamatan/kota' },
          kode_pos: { type: 'string', description: 'Kode pos kalau lead menyebutkan' },
        },
        required: ['paket', 'pembayaran', 'kecamatan', 'kota', 'nama', 'alamat'],
      },
    },
  ];
}

const ORDER_RULE =
  "ORDER: Kalau lead mau beli, kumpulkan: paket (B1G1/B2G2), COD atau transfer, nama, alamat jalan, kecamatan, kota. Tanya yang belum ada secara natural, 1-2 hal per balasan. Untuk ongkir, WAJIB pakai tool cek_ongkir, jangan menebak. Pengiriman selalu JNT dari gudang Surabaya. COD kena biaya 3% dari total (produk + ongkir). Sebelum buat_order, kirim ringkasan (paket, nama, alamat lengkap, pembayaran, ongkir, total) dan minta lead konfirmasi. Setelah order berhasil: kalau transfer, kirim link pembayaran dari hasil tool; kalau COD, bilang paket segera diproses dan bayar ke kurir saat diterima.";

// Susun konteks untuk Claude dari payload webhook Wablas + baris leads_context.
// Mengembalikan null kalau bot harus diam (lead sedang ditangani manusia).

const MAX_HISTORY = 20;
const MODEL = 'claude-haiku-4-5-20251001';
const MAX_TOKENS = 500;

const PRODUCT_PATTERNS = [
  ['KitJelangNikah', /\b(nikah|menikah|pernikahan|wedding|kit jelang nikah|kitjelangnikah)\b/i],
  ['KarierKit', /\b(cv|karier|karir|lamaran kerja|ats|karierkit)\b/i],
  ['SalGlow', /\b(salglow|salep|glowing|flek|bekas jerawat|filo)\b/i],
];

// Kode ref dari landing page, contoh "KJN-7Q2MX". Prefix menentukan produk.
const REF_PATTERN = /\b(SG|KK|KJN)-([A-Z0-9]{5})\b/;
const REF_PRODUCTS = { SG: 'SalGlow', KK: 'KarierKit', KJN: 'KitJelangNikah' };

const CLOSING_PATTERNS = [
  /\bcod\b/i,
  /\b(sudah|udah|udh|sdh) (bayar|transfer|tf)\b/i,
  /\b(saya|aku|sy) (ambil|order|pesan|mau order)\b/i,
  /\boke? deal\b/i,
  /^\s*gas+\b/i,
  /\bbukti (transfer|tf)\b/i,
];

const MEDIA_LABELS = {
  image: '[Lead mengirim gambar]',
  video: '[Lead mengirim video]',
  audio: '[Lead mengirim voice note]',
  ptt: '[Lead mengirim voice note]',
  document: '[Lead mengirim dokumen]',
  sticker: '[Lead mengirim stiker]',
};

// Produk yang disebut eksplisit di pesan, atau null kalau tidak ada.
function detectProduct(text) {
  for (const [product, pattern] of PRODUCT_PATTERNS) {
    if (pattern.test(text)) return product;
  }
  return null;
}

function extractRef(text) {
  const m = String(text || '').toUpperCase().match(REF_PATTERN);
  return m ? { ref: m[0], product: REF_PRODUCTS[m[1]] } : null;
}

// Produk aktif: kode ref LP > produk yang disebut di pesan ini > produk tersimpan > default.
function resolveProduct(incoming, storedProduct) {
  const fromRef = extractRef(incoming);
  const mentioned = fromRef ? fromRef.product : detectProduct(incoming);
  const product = mentioned || storedProduct || DEFAULT_PRODUCT;
  const switchedFrom = storedProduct && mentioned && mentioned !== storedProduct ? storedProduct : null;
  return { product, switchedFrom, ref: fromRef ? fromRef.ref : null };
}

function isClosingMessage(text) {
  return CLOSING_PATTERNS.some((p) => p.test(text));
}

function normalizeIncoming(body) {
  const text = String(body.message || '').trim();
  if (text) return text;
  return MEDIA_LABELS[body.messageType] || '[Lead mengirim pesan non-teks]';
}

function parseHistory(raw) {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

// Claude butuh pesan pertama ber-role user dan role yang bergantian.
function trimHistory(history) {
  let trimmed = history.slice(-MAX_HISTORY);
  while (trimmed.length && trimmed[0].role !== 'user') trimmed = trimmed.slice(1);
  const merged = [];
  for (const msg of trimmed) {
    const last = merged[merged.length - 1];
    if (last && last.role === msg.role) last.content += '\n' + msg.content;
    else merged.push({ role: msg.role, content: msg.content });
  }
  return merged;
}

// Order terakhir lead kalau masih dalam jendela anti-dobel.
function recentOrder(row, now = Date.now()) {
  if (!row || !row.last_order_id || !row.last_order_at) return null;
  const age = now - new Date(row.last_order_at).getTime();
  return age >= 0 && age < SCALEV.duplicateOrderHours * 3600000 ? row.last_order_id : null;
}

function prepareContext(body, row) {
  if (row && String(row.handoff) === 'true') return null;

  const incoming = normalizeIncoming(body);
  const { product, switchedFrom, ref } = resolveProduct(incoming, row && row.active_product);
  const history = parseHistory(row && row.history);
  history.push({ role: 'user', content: incoming });
  const messages = trimHistory(history);

  const tools = orderTools(product);
  let system = buildSystemPrompt(product);
  if (tools) system += ' ' + ORDER_RULE;
  if (switchedFrom) {
    system += ` KONTEKS: Lead baru saja pindah topik dari ${switchedFrom} ke ${product}. Jawab tentang ${product}; jangan lanjut menawarkan ${switchedFrom} kecuali lead menanyakannya lagi.`;
  }

  return {
    phone: body.phone,
    name: body.pushName || '',
    incoming,
    active_product: product,
    switchedFrom,
    ref: ref || (row && row.ref) || '',
    isClosing: isClosingMessage(incoming),
    lastOrder: recentOrder(row),
    messages,
    requestBody: {
      model: MODEL,
      max_tokens: MAX_TOKENS,
      system,
      messages,
      ...(tools ? { tools } : {}),
    },
  };
}

const body = $('Webhook').first().json.body;
const first = items.length ? items[0].json : null;
const row = first && first.phone ? first : null;
const ctx = prepareContext(body, row);
return ctx ? [{ json: ctx }] : [];

// Konfigurasi Scalev. ID diambil dari output workflow "AI Agent CS - Scalev Setup".

const SCALEV = {
  storeId: 2709, // Filomall Beauty
  storeUniqueId: 'store_WQ9th267cKN4103Qini2iUW5',
  warehouseCity: 'Surabaya', // gudang asal
  providerCode: 'mengantar',
  courierPattern: /j\s*&?\s*t|jnt/i, // JNT (J&T Express)
  codFeeRate: 0.03, // 3% dari (harga produk + ongkir)
  codFeeName: 'Biaya COD 3%',
  duplicateOrderHours: 6, // cegah order dobel dari nomor yang sama
};

// Paket yang bisa di-order lewat bot. variantId = integer, variantUniqueId = string "variant_...".
const PACKAGES = {
  SalGlow: {
    B1G1: {
      label: 'SalGlow Beli 1 Gratis 1',
      price: 139000,
      weight: 200, // gram, total paket
      items: [{ variantId: 8419, variantUniqueId: 'variant_T2ffVOfNELb6rwSTNTf9xw8A', qty: 1 }], // 2 Salep Glowing Filo (139.000)
    },
    B2G2: {
      label: 'SalGlow Beli 2 Gratis 2',
      price: 219000,
      weight: 400,
      items: [{ variantId: 8421, variantUniqueId: 'variant_EWWpG6ef8GdXo617vHyFEyP6', qty: 1 }], // 4 Salep Glowing Filo (219.000)
    },
  },
};

// Langkah-langkah tool Scalev: lokasi → gudang → kurir JNT → total → order.
// Setiap fungsi murni; request HTTP-nya dilakukan node n8n di antaranya.

function paymentMethod(pembayaran) {
  return pembayaran === 'cod' ? 'cod' : 'bank_transfer';
}

function rupiah(n) {
  return 'Rp' + Math.round(n).toLocaleString('id-ID');
}

function normalize(s) {
  return String(s || '').toLowerCase().replace(/^(kec\.?|kecamatan|kab\.?|kabupaten|kota)\s+/g, '').trim();
}

// Mulai tool: validasi input + paket.
function startTool(toolUse, ctx) {
  const input = toolUse.input || {};
  const pkg = (PACKAGES[ctx.active_product] || {})[input.paket];
  const base = { toolUseId: toolUse.id, tool: toolUse.name, input, phone: ctx.phone };
  if (!pkg) return { ...base, ok: false, error: `Paket "${input.paket}" tidak tersedia untuk ${ctx.active_product}.` };
  if (toolUse.name === 'buat_order' && ctx.lastOrder) {
    return { ...base, ok: false, error: `Lead ini sudah punya order ${ctx.lastOrder} dalam ${SCALEV.duplicateOrderHours} jam terakhir. Jangan buat order baru; minta tim CS membantu kalau lead mau mengubah order. [HANDOFF]` };
  }
  return { ...base, ok: true, pkg, search: normalize(input.kecamatan) };
}

// Pilih lokasi dari GET /v3/locations?search=<kecamatan>.
function pickLocation(state, response) {
  if (!state.ok) return state;
  const list = (response && response.data) || [];
  const city = normalize(state.input.kota);
  const matches = city ? list.filter((l) => normalize(l.city_name).includes(city)) : list;
  if (matches.length === 1 || (matches.length > 1 && matches.every((m) => m.id === matches[0].id))) {
    return { ...state, location: matches[0] };
  }
  if (!matches.length) {
    return { ...state, ok: false, error: `Kecamatan "${state.input.kecamatan}, ${state.input.kota}" tidak ditemukan. Minta lead cek ejaan kecamatan & kota.` };
  }
  const options = matches.slice(0, 5).map((m) => m.display).join('; ');
  return { ...state, ok: false, error: `Ada beberapa lokasi cocok: ${options}. Tanyakan ke lead yang mana.` };
}

function warehouseRequest(state) {
  return {
    store_id: SCALEV.storeId,
    destination_id: state.location.id,
    variants: state.pkg.items.map((i) => ({ variant_id: i.variantId, qty: i.qty })),
  };
}

// Pilih gudang Surabaya dari POST /v3/shipping-costs/search-warehouse.
function pickWarehouse(state, response) {
  if (!state.ok) return state;
  const list = ((response && response.data) || []).map((d) => d.warehouse).filter(Boolean);
  const city = normalize(SCALEV.warehouseCity);
  const wh = list.find((w) => normalize((w.warehouse_address || {}).city).includes(city)) || list[0];
  if (!wh) return { ...state, ok: false, error: 'Gudang tidak ditemukan untuk paket ini. [HANDOFF]', internal: response };
  return { ...state, warehouse: { id: wh.id, uniqueId: wh.unique_id, name: wh.name } };
}

function courierRequest(state) {
  return {
    store_id: SCALEV.storeId,
    warehouse_id: state.warehouse.id,
    location_id: state.location.id,
    payment_method: paymentMethod(state.input.pembayaran),
    weight: state.pkg.weight,
    ...(state.input.kode_pos ? { postal_code: String(state.input.kode_pos) } : {}),
  };
}

// Pilih layanan JNT via Mengantar (termurah), hitung total.
function pickCourier(state, response) {
  if (!state.ok) return state;
  const isCod = state.input.pembayaran === 'cod';
  const services = ((response && response.data) || []).filter((s) => {
    const cs = s.courier_service || {};
    const courier = cs.courier || {};
    return s.shipment_provider_code === SCALEV.providerCode &&
      SCALEV.courierPattern.test(`${courier.code} ${courier.name} ${cs.name}`) &&
      (!isCod || s.is_cod);
  }).sort((a, b) => a.cost - b.cost);

  if (!services.length) {
    const why = isCod ? 'JNT COD tidak tersedia ke lokasi ini. Tawarkan transfer.' : 'JNT tidak tersedia ke lokasi ini. [HANDOFF]';
    // Untuk admin: kurir apa saja yang sebenarnya dikembalikan Scalev.
    const available = ((response && response.data) || []).map((s) => {
      const cs = s.courier_service || {};
      return `${(cs.courier || {}).name} ${cs.name} via ${s.shipment_provider_code || '-'}${s.is_cod ? ' (COD)' : ''}`;
    });
    return { ...state, ok: false, error: why, kurir_tersedia: available };
  }
  const svc = services[0];
  const price = state.pkg.price;
  const shipping = svc.cost;
  const codFee = isCod ? Math.ceil((price + shipping) * SCALEV.codFeeRate) : 0;
  return {
    ...state,
    courier: { id: svc.courier_service.id, name: `${svc.courier_service.courier.name} ${svc.courier_service.name}`, etd: svc.etd },
    totals: { price, shipping, codFee, total: price + shipping + codFee },
  };
}

// Hanya membuat order. Bot sengaja TIDAK memanggil generate-awb / Request Pickup:
// pickup ditangani langganan pickup sendiri di Mengantar.
function orderRequest(state, ctx) {
  const i = state.input;
  const body = {
    store_unique_id: SCALEV.storeUniqueId,
    customer_name: i.nama,
    customer_phone: state.phone,
    address: i.alamat,
    location_id: state.location.id,
    warehouse_unique_id: state.warehouse.uniqueId,
    courier_service_id: state.courier.id,
    shipping_cost: state.totals.shipping,
    shipment_provider_code: SCALEV.providerCode,
    payment_method: paymentMethod(i.pembayaran),
    ordervariants: state.pkg.items.map((it) => ({ variant_unique_id: it.variantUniqueId, quantity: it.qty })),
    notes: `Order via AI CS WhatsApp${ctx.ref ? ' | ref ' + ctx.ref : ''}`,
    metadata: { source: 'ai-agent-cs', ref: ctx.ref || '' },
  };
  if (i.kode_pos) body.postal_code = String(i.kode_pos);
  if (state.totals.codFee) {
    body.other_income = state.totals.codFee;
    body.other_income_name = SCALEV.codFeeName;
  }
  return body;
}

// Susun tool_result untuk Claude + data ringkas untuk notif & penyimpanan.
function toolResult(state, orderResponse) {
  let content;
  let order = null;
  if (!state.ok) {
    content = { ok: false, error: state.error };
  } else {
    const t = state.totals;
    content = {
      ok: true,
      paket: state.pkg.label,
      tujuan: state.location.display,
      kurir: state.courier.name,
      estimasi: state.courier.etd,
      harga_produk: rupiah(t.price),
      ongkir: rupiah(t.shipping),
      biaya_cod: t.codFee ? rupiah(t.codFee) : null,
      total: rupiah(t.total),
    };
    if (state.tool === 'buat_order') {
      if (orderResponse && orderResponse.order_id) {
        order = { id: orderResponse.id, orderId: orderResponse.order_id, total: t.total, method: state.input.pembayaran };
        content.order_id = orderResponse.order_id;
        if (state.input.pembayaran !== 'cod') content.link_pembayaran = orderResponse.public_order_url || orderResponse.payment_url;
      } else {
        const msg = (orderResponse && (orderResponse.message || (orderResponse.error && orderResponse.error.message))) || 'gagal';
        content = { ok: false, error: `Order gagal dibuat (${msg}). Bilang tim CS akan bantu proses. [HANDOFF]` };
      }
    }
  }
  return {
    block: { type: 'tool_result', tool_use_id: state.toolUseId, content: JSON.stringify(content), is_error: !content.ok },
    order,
  };
}

